Start-Sleep -Seconds 4
$left = Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -and $_.CommandLine -match 'rootmc-ava' }
if ($left) {
  $left | ForEach-Object { Write-Output "EXTRA still alive PID $($_.ProcessId) Name=$($_.Name) Cmd=$($_.CommandLine)"; Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
  Start-Sleep -Seconds 2
}
$left2 = Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -and $_.CommandLine -match 'rootmc-ava' }
Write-Output "Remaining rootmc-ava count: $(@($left2).Count)"

$portInUse = Get-NetTCPConnection -LocalPort 8787 -ErrorAction SilentlyContinue | Where-Object { $_.State -eq 'Listen' }
if ($portInUse) {
  Write-Output "Port 8787 STILL IN USE by PID(s): $($portInUse.OwningProcess -join ', ')"
  $portInUse | ForEach-Object { Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue }
  Start-Sleep -Seconds 2
  $portInUse2 = Get-NetTCPConnection -LocalPort 8787 -ErrorAction SilentlyContinue | Where-Object { $_.State -eq 'Listen' }
  if ($portInUse2) { Write-Output "Port 8787 still busy after kill." } else { Write-Output "Port 8787 is free." }
} else {
  Write-Output "Port 8787 is free."
}

$livePath = 'D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data\liveness.json'
if (Test-Path -LiteralPath $livePath) {
  Remove-Item -LiteralPath $livePath -Force
  Write-Output "Deleted liveness.json"
} else {
  Write-Output "liveness.json not present"
}

$env:AVA_NO_STATUS_WINDOW = '1'
$p = Start-Process -FilePath 'C:\Program Files\nodejs\node.exe' -ArgumentList 'src/index.mjs' -WorkingDirectory 'D:\.1 Work Stations\RootMC\Web Files\rootmc-ava' -WindowStyle Hidden -PassThru
Write-Output "Started index PID $($p.Id)"
Write-Output "Waiting 10 seconds..."
Start-Sleep -Seconds 10
Write-Output "Wait complete."

# List rootmc-ava node PIDs with roles
$procs = Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'node.exe' -and $_.CommandLine -and $_.CommandLine -match 'rootmc-ava' }
$roles = @()
foreach ($proc in $procs) {
  $role = 'other'
  if ($proc.CommandLine -match 'src[/\\]index\.mjs') { $role = 'index' }
  elseif ($proc.CommandLine -match 'src[/\\]server\.mjs') { $role = 'server' }
  elseif ($proc.CommandLine -match 'src[/\\]poller\.mjs') { $role = 'poller' }
  $roles += [pscustomobject]@{ PID = $proc.ProcessId; Role = $role; Cmd = $proc.CommandLine }
}
Write-Output '=== PROCESS LIST ==='
$roles | Format-Table -AutoSize | Out-String | Write-Output
$byRole = $roles | Group-Object Role
foreach ($g in $byRole) { Write-Output "$($g.Name): $($g.Count)" }

# Kill duplicates if any
$needKill = $false
foreach ($roleName in @('index','server','poller')) {
  $group = @($roles | Where-Object { $_.Role -eq $roleName } | Sort-Object PID)
  if ($group.Count -gt 1) {
    $needKill = $true
    $keep = $group[0]
    $extras = $group | Select-Object -Skip 1
    Write-Output "DUPLICATE $roleName — keeping PID $($keep.PID), killing: $($extras.PID -join ', ')"
    foreach ($e in $extras) { Stop-Process -Id $e.PID -Force -ErrorAction SilentlyContinue }
  }
}
if ($needKill) {
  Start-Sleep -Seconds 3
  $procs2 = Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'node.exe' -and $_.CommandLine -and $_.CommandLine -match 'rootmc-ava' }
  $roles2 = @()
  foreach ($proc in $procs2) {
    $role = 'other'
    if ($proc.CommandLine -match 'src[/\\]index\.mjs') { $role = 'index' }
    elseif ($proc.CommandLine -match 'src[/\\]server\.mjs') { $role = 'server' }
    elseif ($proc.CommandLine -match 'src[/\\]poller\.mjs') { $role = 'poller' }
    $roles2 += [pscustomobject]@{ PID = $proc.ProcessId; Role = $role }
  }
  Write-Output '=== PROCESS LIST AFTER DEDUPE ==='
  $roles2 | Format-Table -AutoSize | Out-String | Write-Output
}

# Health
Write-Output '=== HEALTH ==='
try {
  $h = Invoke-RestMethod -Uri 'http://127.0.0.1:8787/health' -TimeoutSec 10
  $summary = [ordered]@{
    degraded = $h.degraded
    pollerLive = $h.pollerLive
    onBreak = $h.onBreak
    'gateway.joinWelcomes' = $h.gateway.joinWelcomes
    'gateway.username' = $h.gateway.username
    children = $h.children
  }
  $summary | ConvertTo-Json -Depth 6
} catch {
  Write-Output "HEALTH FAILED: $_"
}

