$eventsPath = 'D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data\status-events.jsonl'
Write-Output '=== STATUS-EVENTS (last 10) ==='
if (Test-Path -LiteralPath $eventsPath) {
