# Kill ALL Ava-related node: rootmc-ava path OR relative src/(index|server|poller).mjs
function Get-AvaProcs {
  Get-CimInstance Win32_Process | Where-Object {
    $_.Name -match '^(node|npm|cmd)\.exe$' -and $_.CommandLine -and (
      $_.CommandLine -match 'rootmc-ava' -or
      $_.CommandLine -match 'src[/\\](index|server|poller)\.mjs'
    )
  }
}
for ($n = 1; $n -le 6; $n++) {
  $all = @(Get-AvaProcs)
  if ($all.Count -eq 0) { Write-Output "Pass ${n}: clean"; break }
  Write-Output "Pass ${n}: killing $($all.Count)"
  foreach ($p in $all) {
    Write-Output "  PID $($p.ProcessId) $($p.Name) :: $($p.CommandLine.Substring(0, [Math]::Min(120, $p.CommandLine.Length)))"
    Stop-Process -Id $p.ProcessId -Force -ErrorAction SilentlyContinue
  }
  Get-NetTCPConnection -LocalPort 8787 -ErrorAction SilentlyContinue | ForEach-Object {
    Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue
  }
  Start-Sleep -Seconds 2
}
Start-Sleep -Seconds 4
$left = @(Get-AvaProcs)
Write-Output "Remaining Ava procs: $($left.Count)"
foreach ($p in $left) { Write-Output "  STILL: PID $($p.ProcessId) $($p.CommandLine)" }
$port = Get-NetTCPConnection -LocalPort 8787 -State Listen -ErrorAction SilentlyContinue
if ($port) { Write-Output "Port 8787 busy: $($port.OwningProcess -join ',')" } else { Write-Output "Port 8787 is free." }

$livePath = 'D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data\liveness.json'
if (Test-Path -LiteralPath $livePath) { Remove-Item -LiteralPath $livePath -Force; Write-Output 'Deleted liveness.json' } else { Write-Output 'liveness.json not present' }

$env:AVA_NO_STATUS_WINDOW = '1'
$started = Start-Process -FilePath 'C:\Program Files\nodejs\node.exe' -ArgumentList 'src/index.mjs' -WorkingDirectory 'D:\.1 Work Stations\RootMC\Web Files\rootmc-ava' -WindowStyle Hidden -PassThru
Write-Output "Started index PID $($started.Id)"
Start-Sleep -Seconds 10

$procs = @(Get-AvaProcs | Where-Object { $_.Name -eq 'node.exe' })
$final = @()
foreach ($proc in $procs) {
  $role = 'other'
  if ($proc.CommandLine -match 'src[/\\]index\.mjs') { $role = 'index' }
  elseif ($proc.CommandLine -match 'src[/\\]server\.mjs') { $role = 'server' }
  elseif ($proc.CommandLine -match 'src[/\\]poller\.mjs') { $role = 'poller' }
  $final += [pscustomobject]@{ PID = $proc.ProcessId; Role = $role; Parent = $proc.ParentProcessId; Cmd = $proc.CommandLine }
}
Write-Output '=== PROCESS LIST ==='
$final | Select-Object PID, Role, Parent | Format-Table -AutoSize | Out-String | Write-Output
Write-Output "index=$(@($final|Where-Object Role -eq 'index').Count) server=$(@($final|Where-Object Role -eq 'server').Count) poller=$(@($final|Where-Object Role -eq 'poller').Count)"

# Deduplicate
foreach ($roleName in @('index','server','poller')) {
  $group = @($final | Where-Object { $_.Role -eq $roleName } | Sort-Object PID)
  if ($group.Count -gt 1) {
    $keep = $group | Where-Object { $_.PID -eq $started.Id -or $_.Parent -eq $started.Id } | Select-Object -First 1
    if (-not $keep) { $keep = $group[0] }
    $extras = $group | Where-Object { $_.PID -ne $keep.PID }
    Write-Output "DUPLICATE ${roleName}: keep $($keep.PID), kill $($extras.PID -join ',')"
    foreach ($e in $extras) { Stop-Process -Id $e.PID -Force -ErrorAction SilentlyContinue }
  }
}
Start-Sleep -Seconds 2
$final2 = @()
foreach ($proc in @(Get-AvaProcs | Where-Object Name -eq 'node.exe')) {
  $role = 'other'
  if ($proc.CommandLine -match 'src[/\\]index\.mjs') { $role = 'index' }
  elseif ($proc.CommandLine -match 'src[/\\]server\.mjs') { $role = 'server' }
  elseif ($proc.CommandLine -match 'src[/\\]poller\.mjs') { $role = 'poller' }
  $final2 += [pscustomobject]@{ PID = $proc.ProcessId; Role = $role; Parent = $proc.ParentProcessId }
}
Write-Output '=== AFTER DEDUPE ==='
